import * as T from './three.module.js';import {LAKE,ensureFishing,castLine,fishingStatus,reelIn,cancelFishing} from './fishing.js?v=life17';
export function installFishing({scene,state,player,modal,toast,save,perform,register,sign,getGrip=()=>null}){const root=new T.Group();root.name='Willow Lake and fishing pier';scene.add(root);const shore=new T.Mesh(new T.RingGeometry(1,1.11,64),new T.MeshStandardMaterial({color:'#a89d7b',roughness:1}));shore.rotation.x=-Math.PI/2;shore.scale.set(LAKE.rx,LAKE.rz,1);shore.position.set(0,.21,110);root.add(shore);const water=new T.Mesh(new T.CircleGeometry(1,64),new T.MeshStandardMaterial({color:'#548f9f',metalness:.12,roughness:.32}));water.rotation.x=-Math.PI/2;water.scale.set(LAKE.rx,LAKE.rz,1);water.position.set(0,.225,110);root.add(water);const wood=new T.MeshStandardMaterial({color:'#a79673',roughness:.9});const planks=new T.InstancedMesh(new T.BoxGeometry(2.7,.07,.46),wood,28),dummy=new T.Object3D();for(let i=0;i<28;i++){dummy.position.set(0,.24,87+i*.5);dummy.updateMatrix();planks.setMatrixAt(i,dummy.matrix);}planks.computeBoundingSphere();root.add(planks);const path=new T.Mesh(new T.PlaneGeometry(2.8,44),new T.MeshStandardMaterial({color:'#b5aa8a',roughness:1}));path.rotation.x=-Math.PI/2;path.position.set(0,.2,65);root.add(path);for(const x of [-1.25,1.25])for(const z of [87,93,99]){const m=new T.Mesh(new T.CylinderGeometry(.07,.09,1.3,7),wood);m.position.set(x,.35,z);root.add(m);}const station={kind:'fishing',x:0,z:104,approach:LAKE.approach};register(root,station);sign('WILLOW LAKE · FISHING',0,3.5,88);
 const float=new T.Mesh(new T.SphereGeometry(.13,10,6),new T.MeshStandardMaterial({color:'#d39066',emissive:'#ad543c',emissiveIntensity:.1}));float.position.set(.4,.35,104);root.add(float);const rod=new T.Group(),shaft=new T.Mesh(new T.CylinderGeometry(.025,.045,3.3,8),new T.MeshStandardMaterial({color:'#574f40',roughness:.75}));shaft.rotation.x=Math.PI/2;shaft.position.z=1.6;rod.add(shaft);scene.add(rod);const lineGeo=new T.BufferGeometry().setFromPoints([new T.Vector3(),new T.Vector3()]),line=new T.Line(lineGeo,new T.LineBasicMaterial({color:'#e0e2c6',transparent:true,opacity:.7}));scene.add(line);let elapsed=0,lastStatus='idle',hudClock=0;
 window.openFishing=()=>{const f=ensureFishing(state);modal('<span class="service-tag">WILLOW LAKE</span><h2>A quiet spot to fish.</h2><p>Walk onto the pier, cast using 1 maize as bait, then watch the float. Reel in when a fish bites. The bite window lasts 10 seconds. Walking away cancels the cast.</p><div class="choice"><button class="primary" onclick="startLakeFishing()">Walk to pier & cast · 1 maize</button><button onclick="reelLakeFish()">Reel in</button><button onclick="stopLakeFishing()">Pack up</button></div><p>'+state.inventory.fish+' fish stored · sell your catch at the exchange.</p>'+f.catches.slice(0,5).map(c=>'<p>'+c.species+' · '+c.weight+' kg</p>').join('')+'<button onclick="openMarket(\'fish\')">Fish market</button>');};
 window.startLakeFishing=()=>perform(station,()=>{try{castLine(state,player.position);save();toast('Line cast. Watch for a bite.');}catch(e){toast(e.message);}},'Cast fishing line','fish');
 window.reelLakeFish=()=>{try{const f=reelIn(state,player.position);save();toast('Caught '+f.species+' · '+f.weight+' kg!');}catch(e){save();toast(e.message);}};
 window.stopLakeFishing=()=>{cancelFishing(state);save();document.querySelector('dialog').close();};
 return {root,water,rod,line,tick(dt){elapsed+=dt;let status=fishingStatus(state);if(state.fishing?.cast&&Math.hypot(player.position.x,player.position.z-97)>1.8){cancelFishing(state);save();status='idle';toast('Line packed up as you left the pier.');}const active=status!=='idle';rod.visible=line.visible=float.visible=active;if(active){const grip=getGrip();rod.position.set(grip?.x??player.position.x+.35,grip?.y??1.7,grip?.z??player.position.z+.2);rod.lookAt(.4,rod.position.y,104);float.position.y=.35+Math.sin(elapsed*(status==='bite'?15:2))*(status==='bite'?.12:.025);const start=new T.Vector3(0,0,3.2).applyQuaternion(rod.quaternion).add(rod.position),p=lineGeo.attributes.position;p.setXYZ(0,start.x,start.y,start.z);p.setXYZ(1,.4,float.position.y,104);p.needsUpdate=true;lineGeo.computeBoundingSphere();}
 hudClock+=dt;if(hudClock>.2){hudClock=0;const hud=document.querySelector('#fishing-hud');if(hud){hud.hidden=!active;const label=document.querySelector('#fishing-readout');if(label)label.textContent=status==='bite'?'Fish biting! Reel in now':status==='missed'?'Fish escaped · pack up or reel in':'Waiting for a bite…';}}if(status==='bite'&&lastStatus!==status)toast('A fish is biting! Reel in.');lastStatus=status;}};
}
